# homebrew/verify.star - Verify phase for Homebrew

def verify():
    """Verify Homebrew installation."""
    homebrew_prefix = _get_homebrew_prefix()
    brew_path = f"{homebrew_prefix}/bin/brew"

    # Check if brew binary exists
    if not fs.exists(brew_path):
        fail(f"Homebrew binary not found at {brew_path}")

    # Test brew --version command
    result = shell.exec(
        f"{brew_path} --version",
        allowed_commands=["brew"],
    )

    if not result.success:
        fail("brew --version command failed")

    if "Homebrew" not in result.stdout:
        fail("brew --version output doesn't contain 'Homebrew'")

    # Test basic functionality
    result = shell.exec(
        f"{brew_path} list",
        allowed_commands=["brew"],
    )

    if not result.success:
        fail("brew list command failed")

    return {"verify": True}

def _get_homebrew_prefix():
    """Get the correct Homebrew prefix for this platform/architecture."""
    if platform.os == "darwin":
        if platform.arch == "arm64":
            return "/opt/homebrew"
        else:
            return "/usr/local"
    elif platform.os == "linux":
        return "/home/linuxbrew/.linuxbrew"
    else:
        fail(f"Unsupported platform: {platform.os}")

def rollback():
    """No rollback needed for verify phase."""
    pass
